INSERT INTO "public"."dev_lessons" ("id", "theme_id", "theme_name", "development_mode", "age_group", "lesson_number", "title", "biblical_reference", "biblical_story", "reflection", "challenge", "final_message", "share_summary", "created_at") VALUES
('d62c3014-5880-404f-a37c-88353ae2dc55', 'perseveranca', 'Perseverança', 'personal', 'adulto', 7, 'A Certeza da Colheita Fiel', 'Gálatas 6:9-10', 'Paulo escreve às comunidades da Galácia, onde muitos crentes enfrentavam desgaste e desânimo após conflitos doutrinários e dificuldades cotidianas. O apóstolo utiliza a metáfora da semeadura e da ceifa para renovar o vigor dos fiéis. Ele os exorta com firmeza a não esmorecerem na prática do bem, pois a colheita espiritual possui uma data certa, condicionada à perseverança e à recusa em desistir. Enquanto houver oportunidade nesta vida, o cristão deve agir ativamente em favor de todos os homens, dedicando especial zelo e fidelidade à família da fé. Paulo lembra aos irmãos que o serviço cristão silencioso não é vão diante de Deus, mas uma semente eterna que certamente florescerá no tempo oportuno determinado pela soberania divina.', 'A rotina de fazer o bem muitas vezes é marcada pelo cansaço e pela ausência de resultados imediatos. Quando o retorno parece inexistente, a tentação de desanimar ou agir com negligência se torna real. Contudo, a maturidade cristã exige autogoverno e fidelidade contínua, mesmo sob fadiga. A colheita espiritual não segue o ritmo da nossa pressa, mas o cronograma perfeito de Deus. Perseverar no bem sem recuar é a prova máxima de integridade e confiança no Senhor, que honra cada ato de obediência.', 'Pratique hoje uma boa ação concreta em favor de alguém, sem esperar reconhecimento.', 'Quem persevera na semeadura correta colherá no tempo estabelecido por Deus.', 'Em Gálatas 6:9-10, o apóstolo Paulo nos instrui a não esmorecer na prática do bem, garantindo que colheremos no devido tempo se não desfalecermos.
INSERT INTO "public"."dev_questions" ("id", "lesson_id", "question_text", "display_order") VALUES
('49e3a387-6405-480e-bebd-8dac1c939185', 'd62c3014-5880-404f-a37c-88353ae2dc55', 'De acordo com Gálatas 6:9-10, qual é a condição para que a colheita no tempo certo aconteça?', 1),
('8f8a4bfa-4e00-4078-8bde-76062bcff870', 'd62c3014-5880-404f-a37c-88353ae2dc55', 'Em quais áreas da sua vida diária o cansaço mais tem tentado você a deixar de fazer o bem?', 2),
