INSERT INTO "public"."dev_prayers" ("id", "lesson_id", "role", "text_content", "display_order") VALUES
('8cf71939-b774-4f3c-8136-22fc1081ba73', 'd62c3014-5880-404f-a37c-88353ae2dc55', 'Individual', 'Senhor Deus, reconheço que muitas vezes o cansaço e a demora dos frutos tentam enfraquecer minha disposição para o bem. Concede-me autogoverno, paciência e firmeza para perseverar em cada ato de obediência e serviço. Guarda o meu coração contra o desânimo e ajuda-me a confiar plenamente que o Teu tempo para a colheita é perfeito e fiel. Em nome de Jesus, amém.', 1),
('fe0f565c-deaf-4198-beef-7c770394923d', '45a668ed-ab58-4243-a6a5-f501816e7a0c', 'Pai', 'Senhor, ensina nossos corações a perseverar na prática do bem sem desanimar com a espera.', 1),
('f5209558-153c-43ed-a3dd-5fa7dd4685ed', '45a668ed-ab58-4243-a6a5-f501816e7a0c', 'Filho', 'Jesus, ajuda meu coração a ser obediente e carinhoso, mesmo quando eu me sentir cansado.', 2),
('2f502318-0ee3-4e84-8866-1a6c24ba1783', '45a668ed-ab58-4243-a6a5-f501816e7a0c', 'Juntos', 'Pai do Céu, rega a nossa casa com Teu amor para colhermos frutos de paz no Teu tempo. Amém.', 3),
('0ea3f56d-182a-469b-b666-501fec52824d', 'b72d64be-0e3c-44d7-9ca1-fea7fe11a8d9', 'Pai', 'Senhor, dai-nos paciência para perseverar no bem e guiar nossa família com firmeza e fé.', 1),
('542ba9c0-152e-4a6c-9cc7-13e0c9f8ab1a', 'b72d64be-0e3c-44d7-9ca1-fea7fe11a8d9', 'Filho', 'Pai celestial, ajuda-me a não desanimar nas minhas responsabilidades e a sempre escolher o caminho certo.', 2),
('22ee807c-f584-4364-b935-9eeb44085c0f', 'b72d64be-0e3c-44d7-9ca1-fea7fe11a8d9', 'Juntos', 'Deus eterno, confiamos que a nossa colheita virá no Teu tempo. Amém.', 3),
('6e254e50-7ddf-48ac-8347-355772d320a9', 'c674dd4f-e06e-43ae-902c-f5b321cc34bd', 'Pai', 'Senhor, capacita-me a guiar meu filho pelo exemplo diário de constância e integridade cristã.', 1),
('9e3c8219-5461-4045-b779-86d63c683ae2', 'c674dd4f-e06e-43ae-902c-f5b321cc34bd', 'Filho', 'Pai celestial, fortalece minha vontade para rejeitar o pecado e perseverar no caminho correto.', 2),
('4f6e0227-20c8-4122-94f1-7c0f11e647ea', 'c674dd4f-e06e-43ae-902c-f5b321cc34bd', 'Juntos', 'Senhor Deus, concede-nos perseverança inabalável para semearmos o bem até a colheita eterna. Amém.', 3),
('493e86c7-c23e-45b9-b4ac-1391d3630dcb', 'cc338eb5-d5c2-44e6-8180-056d05736cfa', 'Individual', 'Senhor meu Deus, concede-me sabedoria para compreender o valor da disciplina e das provações. Que em meio às dificuldades do dia a dia eu não me deixe vencer pela murmuração ou pela pressa. Forja em mim um caráter íntegro e paciente, capaz de suportar as pressões com fidelidade e autogoverno. Que a Tua graça me sustente em retidão até o fim. Amém.', 1),
('ce6575b9-f3b0-496d-93e3-236bca8171b9', 'cda58e7a-1883-4972-a7f5-8493b614cf30', 'Pai', 'Senhor, ajuda nossos filhos a entenderem que os momentos difíceis nos ensinam a crescer com raízes firmes em Ti.', 1),
('59d8bd45-909f-4f96-bd3b-eba014973902', 'cda58e7a-1883-4972-a7f5-8493b614cf30', 'Filho', 'Papai do Céu, me dá paciência e bom ânimo quando eu não conseguir fazer algo de primeira.', 2),
('e5a3acb1-53b3-43db-9762-dad41d37ea3d', 'cda58e7a-1883-4972-a7f5-8493b614cf30', 'Juntos', 'Amém! Ensina nossa família a confiar em Ti e a nunca desistir diante das dificuldades.', 3),
('3613cf19-7190-4a58-a6c8-408514a09faf', '98af54c0-81b3-47d2-a965-cf47f1b3c953', 'Pai', 'Senhor, ajuda-me a guiar minha casa com firmeza e paciência em cada provação.', 1),
('4e08ec9a-8d37-482c-bd1c-8a6ba9776fd9', '98af54c0-81b3-47d2-a965-cf47f1b3c953', 'Filho', 'Deus, dá-me coragem para não desistir diante dos estudos e das pressões diárias.', 2),
('436e9557-5887-4710-8cef-080b91e338ec', '98af54c0-81b3-47d2-a965-cf47f1b3c953', 'Juntos', 'Pai celestial, molda o nosso caráter para sermos fiéis e perseverantes até o fim. Amém.', 3),
('6b6814b5-0cf0-40d0-a9e8-0f8276819885', '7e35da2c-0ccf-44a6-8aab-2d043de72208', 'Pai', 'Senhor, dá-me sabedoria para ensinar meu filho a amar a disciplina e a integridade.', 1),
('13973067-8e99-4928-8c2a-21e7c28cecb7', '7e35da2c-0ccf-44a6-8aab-2d043de72208', 'Filho', 'Deus, fortalece meu coração para suportar as provações e fazer escolhas corretas no secreto.', 2),
('c0dfbe04-5312-446a-9d55-762177d97b30', '7e35da2c-0ccf-44a6-8aab-2d043de72208', 'Juntos', 'Pai celestial, ajuda a nossa família a perseverar na verdade em qualquer situação. Amém.', 3),
('2bfe9393-0a9d-4581-b81b-014e66c68276', '9a1aaa1c-2584-452e-9c66-b8c56136d551', 'Individual', 'Senhor meu Deus, fortalece meu espírito para que eu permaneça firme em Tua verdade. Dá-me autogoverno e paciência para suportar as tribulações sem abrir mão da minha integridade. Que a minha vida seja uma corrida marcada pela perseverança e que, ao final da minha jornada, eu possa testemunhar que guardei a fé inabalável em Ti. Amém.', 1),
('ade7c013-8646-4a4c-aa8e-d740a9d7b799', '1d8b5a2b-7fd6-4d1b-a953-124e5b1219c3', 'Pai', 'Senhor, ajuda nossa família a guardar a fé e a seguir Teus passos todos os dias.', 1),
('1557e9d9-1e7b-4530-80b8-1080cb3d0b86', '1d8b5a2b-7fd6-4d1b-a953-124e5b1219c3', 'Filho', 'Papai do Céu, segura bem forte a minha mãozinha para eu nunca desistir de Te amar.', 2),
('d1f7a583-e6ac-4ef7-8231-01f0a8faf36c', '1d8b5a2b-7fd6-4d1b-a953-124e5b1219c3', 'Juntos', 'Obrigado, Jesus, por nos dar forças para corrermos juntos até o Teu Reino. Amém!', 3),
('bf603c7b-10d4-4c36-a45e-042ab02ff037', '14d79e3b-c373-4ccf-800a-305595ea08d6', 'Pai', 'Senhor, dá-nos firmeza para liderar esta casa no Teu caminho, sem desviar nem desanimar diante das pressões do mundo.', 1),
('a7b46bfb-1e39-40e4-a0e7-81d4c1f119ba', '14d79e3b-c373-4ccf-800a-305595ea08d6', 'Filho', 'Jesus, ajuda-me a não ter vergonha da minha fé e a permanecer fiel a Ti mesmo quando for difícil.', 2),
('058ffa19-6a3b-419e-bbcc-1941848b2000', '14d79e3b-c373-4ccf-800a-305595ea08d6', 'Juntos', 'Pai amado, ajuda a nossa família a combater o bom combate até o fim, guardando sempre a fé. Amém.', 3),
('2afdad9f-8bc2-45e4-a72e-682f0e0f1fe0', 'f4569023-2eb4-4a5c-a856-278de5439d57', 'Pai', 'Senhor, dá-me sabedoria e firmeza para liderar pelo exemplo, ensinando a fidelidade aos Teus mandamentos.', 1),
('687286f2-ed32-49bd-ab7d-e5d515094ea7', 'f4569023-2eb4-4a5c-a856-278de5439d57', 'Filho', 'Pai celeste, fortalece meu coração para rejeitar as ilusões do pecado e perseverar em retidão nas minhas escolhas.', 2),
('b9090664-ff7f-4547-8dcc-feba6e5532a9', 'f4569023-2eb4-4a5c-a856-278de5439d57', 'Juntos', 'Senhor Deus, ajuda a nossa família a guardar a fé inegociável até o fim da nossa caminhada. Amém.', 3),
('421e6a56-7bbf-43b4-a48a-51a1540c8ade', 'caaccf38-ec6c-4d9b-8ec6-5296f16d7d27', 'Individual', 'Senhor Deus, reconheço que a verdadeira firmeza vem da comunhão Contigo. Fortalece o meu espírito para que eu não vacile diante das provações diárias. Ensina-me a manter a integridade, a guardar a fé e a agir com fidelidade inabalável em cada decisão. Que a Tua promessa eterna guie os meus passos e firme a minha conduta hoje e sempre. Amém.', 1),
('6fa21248-dd64-43f1-a073-10473133e38e', '463f5d9f-0be0-4bc7-8b8c-af98099c1593', 'Pai', 'Senhor, ajuda-nos a ensinar nossos filhos a permanecerem firmes e fiéis ao Teu amor todos os dias.', 1),
('035597ac-2575-4ca1-8981-e1b6dc411582', '463f5d9f-0be0-4bc7-8b8c-af98099c1593', 'Filho', 'Jesus, obrigado por cuidar de mim e me dar forças para nunca desistir do que é certo.', 2),
('a787873d-9680-44fb-b9d9-db9b5d97289f', '463f5d9f-0be0-4bc7-8b8c-af98099c1593', 'Juntos', 'Amém! Cremos na Tua promessa e queremos viver para sempre seguros em Tua presença.', 3),
('5d9bb63e-e680-4c79-9b1a-0591d79bdab9', 'ede927a1-428a-460a-b4f6-279b5a1eff57', 'Pai', 'Senhor, fortalece nossos filhos contra as pressões do mundo e dá-nos sabedoria para sermos modelos de perseverança inabalável.', 1),
('a3ba157f-6309-4504-b86f-91ce85cb20d6', 'ede927a1-428a-460a-b4f6-279b5a1eff57', 'Filho', 'Jesus, ajuda-me a ser fiel nas minhas amizades e decisões diárias, sem ter medo de defender o que é certo.', 2),
('6fa7b40b-7b6a-477a-8493-9fe9b5a8eb30', 'ede927a1-428a-460a-b4f6-279b5a1eff57', 'Juntos', 'Pai Celestial, guardamos Tua Palavra no coração para vencermos os testes da vida e reinarmos eternamente contigo. Amém.', 3),
('ccf89816-e3fb-45b7-9088-49ea5dcbbe12', '594dc0b8-ca92-4ab7-8ec9-22184c981304', 'Pai', 'Senhor, fortalece meu filho para resistir às pressões do mundo e permanecer inabalável na verdade.', 1),
('8275bcc2-3856-49af-bda2-ffc620e2b537', '594dc0b8-ca92-4ab7-8ec9-22184c981304', 'Filho', 'Pai celestial, dá-me coragem para honrar Teu nome nas minhas decisões secretas e guardar a minha coroa.', 2),
('faeeaf43-2cbb-4b04-a2c5-e4caf6de2ce9', '594dc0b8-ca92-4ab7-8ec9-22184c981304', 'Juntos', 'Senhor Jesus, ajuda nossa família a perseverar com integridade até recebermos a Tua recompensa eterna. Amém.', 3);
